mapper.select:
SELECT id, workspace_id, connection_id, title, topic, audience, style,
       output_format, status, version, created_at, updated_at
FROM content_project


        workspace_id = #{workspaceId}


ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.insert:
